import {content,interests} from './content.js';
import {games,gameResult} from './games.js';
import {domains,gestures,observedStatus} from './reporting.js';
import {questionResult,esc} from './core.js';
export const situationsFor=d=>d.label==='Sécurité'?['S1']:d.label==='Démarches'?['S2']:d.label==='Recherche Internet'?['S3']:[];
export function knowledgeCounts(p,d){const counts={J:0,E:0,NSP:0,NR:0};for(const q of content.questions.filter(q=>d.questions.includes(q.id)))counts[questionResult(q,p.answers[q.id])]++;return counts;}
export function cardCounts(p,d){const counts={J:0,E:0,NSP:0,NR:0};for(const g of games.filter(g=>g.domain===d.label)){const r=gameResult(g,p.answers);if(r.status==='NSP')counts.NSP+=r.total;else{counts.J+=r.correct;counts.E+=r.answered-r.correct;counts.NR+=r.total-r.answered;}}return counts;}
export function domainEvidence(p,d){
 const q=knowledgeCounts(p,d),g=cardCounts(p,d),obs=observedStatus(p,d),ss=situationsFor(d).map(id=>p.observations?.[id]);
 const need=q.E+q.NSP+g.E+g.NSP>0||obs==='help'||ss.some(v=>['C','R'].includes(v));
 const practical=gestures.filter(x=>d.challenges.includes(x.challenge));
 const observed=practical.filter(x=>['0','1','2','3'].includes(p.observations?.[x.id])).length;
 const missing=q.NR+g.NR+practical.length-observed+ss.filter(v=>!['P','C','R'].includes(v)).length;
 const evidence=q.J+q.E+q.NSP+g.J+g.E+g.NSP+observed+ss.filter(v=>['P','C','R'].includes(v)).length;
 return {q,g,obs,need,missing,evidence,status:need?'help':!evidence?'unknown':missing?'partial':'ready',requested:p.answers.interests?.includes(d.interest)===true};
}
export function confidenceCases(p,kind){return games.filter(g=>{const r=gameResult(g,p.answers),confidence=p.answers[g.id+'_confidence'];if(r.status!=='done')return false;return kind==='reassure'?confidence==='Hésitant'&&r.correct===r.total:confidence==='Sûr de moi'&&r.correct<r.total;});}
export function selectPeople(ps,domainIndex,metric){
 if(metric==='finished')return ps.filter(p=>p.finished);
 if(metric==='ongoing')return ps.filter(p=>!p.finished);
 if(metric==='reassure'||metric==='verify')return ps.filter(p=>confidenceCases(p,metric).length);
 if(metric.startsWith('interest:'))return ps.filter(p=>p.answers.interests?.includes(interests[Number(metric.split(':')[1])]));
 const d=domains[domainIndex];if(!d)return [];
 return ps.filter(p=>{const e=domainEvidence(p,d);if(metric.startsWith('q:'))return e.q[metric.slice(2)]>0;if(metric.startsWith('g:'))return e.g[metric.slice(2)]>0;if(metric.startsWith('obs:'))return e.obs===metric.slice(4);if(metric==='need')return e.need;if(metric==='requested')return e.requested;return false;});
}
export function domainStats(ps){return domains.map(d=>{const es=ps.map(p=>domainEvidence(p,d));return {domain:d,need:es.filter(e=>e.need).length,requested:es.filter(e=>e.requested).length,missing:es.filter(e=>e.missing).length,evidence:es.filter(e=>e.evidence).length,unknown:es.filter(e=>!e.evidence).length};});}
const labels={J:'Juste',E:'À revoir',NSP:'Ne sait pas',NR:'Sans réponse',alone:'Sans aide',help:'Avec aide',unobserved:'À observer',finished:'Terminé',ongoing:'En cours'};
function bar(parts,index,prefix,total){return `<div class="stat-bar" aria-label="${total} éléments au total">${parts.filter(([,n])=>n>0).map(([key,n])=>`<button class="segment seg-${key}" style="flex-basis:${total?n/total*100:0}%;flex-grow:0" data-drill="${index}|${prefix+key}" title="${esc(labels[key])} : ${n} sur ${total}"><span ${total&&n/total<.09?'class="sr-only"':''}>${n}</span><span class="sr-only"> ${esc(labels[key])} sur ${total}</span></button>`).join('')}</div><div class="stat-legend">${parts.map(([key,n])=>`<button class="text-button small" data-drill="${index}|${prefix+key}"><i class="swatch seg-${key}" aria-hidden="true"></i>${labels[key]} : ${n}</button>`).join('')}</div>`;}
function totals(ps,d,fn){return ps.reduce((r,p)=>{const c=fn(p,d);for(const key of Object.keys(r))r[key]+=c[key];return r;},{J:0,E:0,NSP:0,NR:0});}
export function analyticsHtml(ps){
 if(!ps.length)return '<div class="card"><h2>Les graphiques attendent les premiers résultats</h2><p>Importez les fichiers de votre séance ou utilisez la démonstration pour découvrir les vues.</p></div>';
 const statusLabels={help:'Besoin repéré',unknown:'Sans élément',partial:'À compléter',ready:'Repères acquis'};
 const finished=ps.filter(p=>p.finished).length;
 return `<div class="card"><h2>Avancement du groupe</h2><p>${ps.length} participant(s) · ${finished} parcours terminé(s). Terminer ne signifie pas avoir tout renseigné.</p>${bar([['finished',finished],['ongoing',ps.length-finished]],-1,'',ps.length)}</div><div class="card"><h2>Connaissances et mini-jeux</h2><p>Les barres comptent des réponses, pas des personnes. Le total inclut les réponses manquantes. Cliquez sur une couleur ou sa légende pour retrouver les personnes concernées.</p>${domains.map((d,i)=>{const q=totals(ps,d,knowledgeCounts),g=totals(ps,d,cardCounts);return `<section class="stat-domain"><h3>${esc(d.label)}</h3><div class="stat-columns"><div><h4>Questions · ${Object.values(q).reduce((a,b)=>a+b,0)} réponses attendues</h4>${bar(Object.entries(q),i,'q:',Object.values(q).reduce((a,b)=>a+b,0))}</div><div><h4>Cartes des mini-jeux · ${Object.values(g).reduce((a,b)=>a+b,0)} réponses attendues</h4>${bar(Object.entries(g),i,'g:',Object.values(g).reduce((a,b)=>a+b,0))}</div></div></section>`;}).join('')}</div><div class="card"><h2>Autonomie réellement observée</h2><p>Une barre représente ${ps.length} personnes. « À observer » peut inclure des gestes déjà observés : il manque encore des éléments pour conclure.</p>${domains.filter(d=>d.challenges.length).map(d=>{const i=domains.indexOf(d),parts=['alone','help','unobserved'].map(k=>[k,ps.filter(p=>observedStatus(p,d)===k).length]);return `<h3>${esc(d.label)}</h3>${bar(parts,i,'obs:',ps.length)}`;}).join('')}<p class="muted">Les autres domaines ne comportent pas de manipulation observée dans ce diagnostic.</p></div><div class="card"><h2>Confiance et réponses</h2><p>Uniquement les mini-jeux entièrement renseignés avec une confiance déclarée. Ces signaux invitent à discuter ; ils ne décrivent pas la personnalité.</p><div class="stat-columns">${[['reassure','À encourager','mini-jeu(x) réussi(s) avec hésitation'],['verify','À vérifier ensemble','mini-jeu(x) avec erreur malgré une réponse sûre de soi']].map(([k,title,desc])=>{const people=selectPeople(ps,-1,k),cases=ps.reduce((n,p)=>n+confidenceCases(p,k).length,0);return `<button class="signal-card" data-drill="-1|${k}"><strong>${title}</strong><span>${people.length} personne(s)</span><small>${cases} ${desc}</small></button>`;}).join('')}</div></div><div class="card"><h2>Les envies du groupe</h2>${interests.map((interest,i)=>{const n=ps.filter(p=>p.answers.interests?.includes(interest)).length;return `<button class="interest-chart" data-drill="-1|interest:${i}"><span>${esc(interest)}</span><span class="interest-track"><span style="width:${n/ps.length*100}%"></span></span><strong>${n} / ${ps.length}</strong></button>`;}).join('')}</div><div class="card"><h2>Participants et domaines</h2><p>Besoin repéré = au moins une difficulté déclarée par la réponse ou observée par l’animateur. Repères acquis = éléments prévus renseignés sans difficulté repérée, sans certification de maîtrise. Cliquez sur une case pour lire son détail.</p><div class="scroll"><table class="skill-matrix"><caption class="sr-only">Lecture individuelle des neuf domaines</caption><thead><tr><th>Participant</th>${domains.map(d=>`<th>${esc(d.label)}</th>`).join('')}</tr></thead><tbody>${ps.map(p=>`<tr><th>${esc(p.name)}</th>${domains.map((d,i)=>{const e=domainEvidence(p,d);return `<td><button class="matrix-cell cell-${e.status}" data-cell="${esc(p.id)}|${i}">${statusLabels[e.status]}</button></td>`;}).join('')}</tr>`).join('')}</tbody></table></div></div><section id="drilldown" class="card" hidden tabindex="-1"></section>`;
}
export function evidenceHtml(p,d){const e=domainEvidence(p,d);return `<p><strong>${esc(p.name)} · ${esc(d.label)}</strong></p><p>Questions : ${e.q.J} juste(s), ${e.q.E} à revoir, ${e.q.NSP} « ne sait pas », ${e.q.NR} manquante(s).</p><p>Cartes : ${e.g.J} juste(s), ${e.g.E} à revoir, ${e.g.NSP} « ne sait pas », ${e.g.NR} manquante(s).</p><p>Manipulations : ${e.obs?labels[e.obs]:'Non évaluées dans ce domaine'}. ${e.missing} élément(s) restant à renseigner ou observer au total.</p>${situationsFor(d).map(id=>`<p>${id} · Évaluation animateur : ${esc(p.observations?.[id]||'Non observée')}</p>`).join('')}<button class="secondary small" data-person="${esc(p.id)}">Lire les réponses et observations</button>`;}
